class Counter {
  count: number;
  constructor(start: number) {
    this.count = start;
  }
  increment(): void {
    this.count = this.count + 1;
  }
}
const c = new Counter(5);
c.increment();
c.increment();
console.log(c.count);
console.log(c);

class Player {
  name: string;
  score: number = 0;
  constructor(name: string) {
    this.name = name;
  }
  addPoints(points: number): void {
    this.score = this.score + points;
  }
  describe(): string {
    return this.name + ": " + this.score;
  }
}
const p = new Player("Ana");
p.addPoints(10);
console.log(p.describe());

class Account {
  readonly owner: string;
  private balance: number = 0;
  constructor(owner: string) {
    this.owner = owner;
  }
  public deposit(amount: number): void {
    this.balance = this.balance + amount;
  }
  public getBalance(): number {
    return this.balance;
  }
}
const acc = new Account("Ben");
acc.deposit(50);
console.log(acc.owner, acc.getBalance());
console.log(acc);

interface Shape {
  name: string;
  area(): number;
}
class Square implements Shape {
  name: string = "square";
  side: number;
  constructor(side: number) {
    this.side = side;
  }
  area(): number {
    return this.side * this.side;
  }
}
function report(s: Shape): string {
  return s.name + " " + s.area();
}
console.log(report(new Square(3)));

